settings.custom_liquid:
{%- if request.locale.iso_code == 'fr' -%}
  {%- assign nur_rating_text = '4,6/5 avis de testeurs' -%}
  {%- assign nur_rating_label = 'Noté 4,6 sur 5 par nos testeurs' -%}
{%- else -%}
  {%- assign nur_rating_text = '4.6/5 tester reviews' -%}
  {%- assign nur_rating_label = 'Rated 4.6 out of 5 by our testers' -%}
{%- endif -%}
<a class="nur-rating" href="{% if routes.root_url == '/' %}/pages/reviews{% else %}{{ routes.root_url }}/pages/reviews{% endif %}" aria-label="{{ nur_rating_label }}">
  <span class="nur-rating__stars" aria-hidden="true"><span class="nur-rating__fill">★★★★★</span>★★★★★</span>
  <span class="nur-rating__text">{{ nur_rating_text }}</span>
</a>
<style>
  .nur-rating { display: inline-flex; align-items: center; gap: 8px; text-decoration: none; color: #1A1A1A; font-size: 13px; }
  .nur-rating__stars { position: relative; display: inline-block; color: #E5DCC7; letter-spacing: 2px; font-size: 15px; line-height: 1; }
  .nur-rating__fill { position: absolute; inset: 0 auto 0 0; width: 92%; overflow: hidden; white-space: nowrap; color: #C8A96E; }
  .nur-rating__text { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: rgba(26,26,26,0.25); }
  .nur-rating:hover .nur-rating__text { text-decoration-color: #1A1A1A; }
</style>

{%- assign nur_title = closest.product.title | default: product.title -%}
{%- assign nur_title_parts = nur_title | split: ' - ' -%}
<style>
  .nur-pdp-title { margin: 0; }
  .nur-pdp-subtitle { display: block; margin: 6px 0 0; text-transform: none; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 15px; font-weight: 400; letter-spacing: 0.3px; line-height: 1.4; color: #4A4A4A; }
</style>
<h1 class="h3 nur-pdp-title">
  {{- nur_title_parts[0] -}}
  {%- if nur_title_parts.size > 1 -%}
    <span class="visually-hidden"> — </span><span class="nur-pdp-subtitle">{{ nur_title_parts[1] }}</span>
  {%- endif -%}
</h1>

{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = routes.root_url
  if nur_root == '/'
    assign nur_root = ''
  endif
  # Early Access window (same deadline as the Early Access block): 25 Nov 2026 23:59 Paris
  assign nur_now = 'now' | date: '%s' | plus: 0
  assign nur_early = false
  if nur_now < 1795647540
    assign nur_early = true
  endif
-%}
<style>
  .nur-info { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; margin: 8px 0 4px; border-top: 1px solid #ECEAE5; }
  .nur-info__row { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: 16px; padding: 20px 2px; background: none; border: 0; border-bottom: 1px solid #ECEAE5; border-radius: 0; cursor: pointer; font-family: inherit; font-size: 13px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: #1A1A1A; text-align: left; }
  .nur-info__row:hover { color: #C8A96E; }
  a.nur-info__row { text-decoration: none; box-sizing: border-box; }
  .nur-info__row svg { width: 16px; height: 16px; flex-shrink: 0; stroke: currentColor; fill: none; stroke-width: 1.6; }
  .nur-drawer { position: fixed; inset: 0 0 0 auto; margin: 0; width: min(480px, 100vw); max-width: 100vw; height: 100dvh; max-height: 100dvh; padding: 0; border: 0; border-radius: 0; background: #FFFFFF; color: #1A1A1A; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; box-shadow: -12px 0 40px rgba(0,0,0,0.12); overflow: hidden; }
  .nur-drawer[open] { display: flex; flex-direction: column; animation: nur-drawer-in 0.32s ease; }
  .nur-drawer::backdrop { background: rgba(26,26,26,0.45); }
  @keyframes nur-drawer-in { from { transform: translateX(100%); } to { transform: translateX(0); } }
  .nur-drawer__head { display: flex; align-items: center; justify-content: space-between; padding: 26px 32px; border-bottom: 1px solid #ECEAE5; flex-shrink: 0; }
  .nur-drawer__title { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; color: #1A1A1A; }
  .nur-drawer__close { display: flex; align-items: center; justify-content: center; width: 36px; height: 36px; padding: 0; background: none; border: 0; cursor: pointer; color: #1A1A1A; }
  .nur-drawer__close:focus:not(:focus-visible) { outline: none; }
  .nur-drawer__close svg { width: 18px; height: 18px; stroke: currentColor; stroke-width: 1.6; fill: none; }
  .nur-drawer__body { flex: 1; padding: 28px 32px 40px; overflow-y: auto; -webkit-overflow-scrolling: touch; }
  .nur-drawer__body h4 { margin: 0 0 6px; font-size: 14px; font-weight: 700; color: #1A1A1A; }
  .nur-drawer__body p, .nur-drawer__body li { font-size: 14px; line-height: 1.7; color: #4A4A4A; }
  .nur-drawer__body p { margin: 0 0 24px; }
  .nur-drawer__body ul { margin: 0 0 24px; padding-left: 18px; }
  .nur-drawer__body a { color: #1A1A1A; text-decoration: underline; text-underline-offset: 3px; }
  .nur-spec { margin: 0 0 22px; }
  .nur-spec__label { display: block; font-size: 14px; font-weight: 700; color: #1A1A1A; margin-bottom: 4px; }
  .nur-spec__value { font-size: 14px; line-height: 1.7; color: #4A4A4A; }
  .nur-drawer__body .nur-waves { list-style: none; margin: 4px 0 0; padding: 0; }
  .nur-waves li { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; border-bottom: 1px solid #F2EFE8; }
  .nur-waves li span:last-child { font-family: 'Courier New', Courier, monospace; font-weight: 600; color: #1A1A1A; white-space: nowrap; }
  .nur-award-row { display: flex; width: 100%; align-items: center; gap: 14px; margin: 16px 0 0; padding: 16px 18px; background: #F5EFE4; border: 0; border-radius: 0; cursor: pointer; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 15px; font-weight: 700; color: #1A1A1A; text-align: left; }
  .nur-award-row:hover { background: #EFE6D6; }
  .nur-award-row__icon { width: 22px; height: 22px; flex-shrink: 0; fill: none; stroke: #C8A96E; stroke-width: 1.5; stroke-linejoin: round; }
  .nur-award-row__text { flex: 1; }
  .nur-award-row__chev { width: 16px; height: 16px; flex-shrink: 0; fill: none; stroke: currentColor; stroke-width: 1.6; }
  .nur-award__photo { display: block; width: 100%; height: auto; aspect-ratio: 800 / 977; object-fit: cover; margin: 0 0 24px; }
  .nur-award__tag { display: block; font-size: 11px; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: #C8A96E; margin-bottom: 10px; }
  .nur-drawer__body .nur-award__title { margin: 0 0 14px; font-size: 20px; font-weight: 500; line-height: 1.3; color: #1A1A1A; }
  @media (max-width: 749px) {
    .nur-drawer__head { padding: 20px 20px; }
    .nur-drawer__body { padding: 22px 20px 36px; }
  }
</style>

<div class="nur-info">
  {%- comment -%} The specs are a visible section further down the page (EN and FR), so the row jumps there. {%- endcomment -%}
  <a class="nur-info__row" href="#nur-specs">
    <span>{% if nur_fr %}Fiche technique{% else %}Tech specs{% endif %}</span>
    <svg viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </a>
  <button type="button" class="nur-info__row" data-nur-drawer="nur-drawer-faq">
    <span>FAQ</span>
    <svg viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </button>
  <button type="button" class="nur-info__row" data-nur-drawer="nur-drawer-contra">
    <span>{% if nur_fr %}Contre-indications{% else %}Contraindications{% endif %}</span>
    <svg viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </button>
  <button type="button" class="nur-award-row" data-nur-drawer="nur-drawer-award">
    <svg class="nur-award-row__icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2.5l2.1 6.4 6.4 2.1-6.4 2.1L12 19.5l-2.1-6.4L3.5 11l6.4-2.1z"/><path d="M19 15.5l.8 2.2 2.2.8-2.2.8-.8 2.2-.8-2.2-2.2-.8 2.2-.8z"/></svg>
    <span class="nur-award-row__text">{% if nur_fr %}Fondatrice primée pour l’IA en beauté{% else %}Award-winning founder in AI beauty{% endif %}</span>
    <svg class="nur-award-row__chev" viewBox="0 0 24 24" aria-hidden="true"><polyline points="9 6 15 12 9 18"></polyline></svg>
  </button>
</div>

<dialog class="nur-drawer" id="nur-drawer-faq" aria-labelledby="nur-drawer-faq-title">
  <div class="nur-drawer__head">
    <h3 class="nur-drawer__title" id="nur-drawer-faq-title">FAQ</h3>
    <button type="button" class="nur-drawer__close" data-nur-close aria-label="{% if nur_fr %}Fermer{% else %}Close{% endif %}"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>
  <div class="nur-drawer__body">
    {%- if nur_early -%}
    <h4>{% if nur_fr %}Quand vais-je recevoir mon masque&nbsp;?{% else %}When will I receive my mask?{% endif %}</h4>
    <p>{% if nur_fr %}Les réservations faites jusqu’au 25 novembre (23&nbsp;h&nbsp;59, heure de Paris) partent avec notre première expédition de décembre, avec une livraison prévue avant Noël. Vous recevez un numéro de suivi dès l’expédition.{% else %}Reservations made by November 25 (11:59 PM Paris time) are part of our first December shipment, with delivery planned before Christmas. You receive a tracking number as soon as your order ships.{% endif %}</p>
    {%- endif -%}
    <h4>{% if nur_fr %}Comment accéder à NŪR Skincoach&nbsp;?{% else %}How do I access NŪR Skincoach?{% endif %}</h4>
    <p>{% if nur_fr %}Votre carte Gold digitale contient un QR code qui vous donne accès à l’application NŪR Skincoach. Une carte d’accès est aussi incluse dans votre coffret.{% else %}Your digital Gold Card includes a QR code that gives you access to the NŪR Skincoach app. An access card is also included in your box.{% endif %}</p>
    <h4>{% if nur_fr %}Puis-je payer en plusieurs fois&nbsp;?{% else %}Can I pay in instalments?{% endif %}</h4>
    <p>{% if nur_fr %}Oui. Au moment du paiement, choisissez Klarna pour régler en plusieurs fois.{% else %}Yes. At checkout, choose Klarna to pay in instalments.{% endif %}</p>
    <h4>{% if nur_fr %}Comment fonctionne un code promo&nbsp;?{% else %}How do promo codes work?{% endif %}</h4>
    <p>{% if nur_fr %}Saisissez votre code au moment du paiement&nbsp;: il retire 10&nbsp;% du prix complet de votre coffret.{% else %}Enter your code at checkout: it takes 10% off the full price of your set.{% endif %}</p>
    <h4>{% if nur_fr %}Où livrez-vous&nbsp;?{% else %}Where do you ship?{% endif %}</h4>
    <p>{% if nur_fr %}Nous livrons dans le monde entier. Les frais de livraison pour votre pays s’affichent au moment du paiement.{% else %}We ship worldwide. Shipping costs for your country are shown at checkout.{% endif %}</p>
    <h4>{% if nur_fr %}Quelle est la garantie&nbsp;?{% else %}What warranty do I get?{% endif %}</h4>
    <p>{% if nur_fr %}Votre NŪR Protocol est garanti 2 ans.{% else %}Your NŪR Protocol comes with a 2-year warranty.{% endif %}</p>
    <h4>{% if nur_fr %}Une autre question&nbsp;?{% else %}Another question?{% endif %}</h4>
    <p>{% if nur_fr %}Écrivez-nous depuis notre <a href="{{ nur_root }}/pages/contact">page contact</a>&nbsp;: nous vous répondons personnellement.{% else %}Write to us from our <a href="{{ nur_root }}/pages/contact">contact page</a>: we reply personally.{% endif %}</p>
  </div>
</dialog>

<dialog class="nur-drawer" id="nur-drawer-contra" aria-labelledby="nur-drawer-contra-title">
  <div class="nur-drawer__head">
    <h3 class="nur-drawer__title" id="nur-drawer-contra-title">{% if nur_fr %}Contre-indications{% else %}Contraindications{% endif %}</h3>
    <button type="button" class="nur-drawer__close" data-nur-close aria-label="{% if nur_fr %}Fermer{% else %}Close{% endif %}"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>
  <div class="nur-drawer__body">
    <h4>{% if nur_fr %}Qui ne doit pas utiliser NŪR Protocol{% else %}Who should not use NŪR Protocol{% endif %}</h4>
    <p>{% if nur_fr %}D’après la notice d’utilisation, l’appareil ne doit pas être utilisé par&nbsp;:{% else %}According to the user manual, the device should not be used by:{% endif %}</p>
    <ul>
      <li>{% if nur_fr %}les femmes enceintes ou qui allaitent&nbsp;;{% else %}people who are pregnant or breastfeeding;{% endif %}</li>
      <li>{% if nur_fr %}les personnes sensibles à la lumière, ou qui prennent un médicament photosensibilisant&nbsp;;{% else %}people with light sensitivity, or taking medication that can cause photosensitivity;{% endif %}</li>
      <li>{% if nur_fr %}les personnes atteintes d’une maladie héréditaire des yeux ou d’une maladie de peau, comme le lupus, l’eczéma photosensible ou l’albinisme.{% else %}people with a hereditary eye condition or a skin disease, such as lupus, photosensitive eczema or albinism.{% endif %}</li>
    </ul>
    <p>{% if nur_fr %}NŪR Protocol est destiné aux adultes de 18 ans et plus.{% else %}NŪR Protocol is intended for adults aged 18 and over.{% endif %}</p>
    <h4>{% if nur_fr %}Avant la première séance{% else %}Before your first session{% endif %}</h4>
    <p>{% if nur_fr %}Faites un test de sensibilité&nbsp;: posez l’appareil sur l’avant-bras et allumez-le 10 minutes. En cas de rougeur ou de démangeaison, arrêtez et consultez un dermatologue avant toute nouvelle utilisation. Chaque séance se fait sur une peau propre et sèche, sans maquillage.{% else %}Do a sensitivity test: place the device on your forearm and switch it on for 10 minutes. If redness or itching appears, stop and see a dermatologist before using it again. Each session is done on clean, dry skin, without make-up.{% endif %}</p>
    <h4>{% if nur_fr %}Pendant et après la séance{% else %}During and after a session{% endif %}</h4>
    <p>{% if nur_fr %}Les protections oculaires restent en place pendant toute la séance, et l’appareil ne s’utilise pas pendant qu’il charge. Une légère rougeur passagère peut apparaître après la séance&nbsp;; elle disparaît normalement en 1 à 2 heures. En cas de sensation de brûlure ou d’inconfort, arrêtez immédiatement.{% else %}The eye protectors stay in place for the whole session, and the device is not used while it is charging. Slight, temporary redness can appear after a session; it normally fades within 1 to 2 hours. If you feel a burning sensation or any discomfort, stop immediately.{% endif %}</p>
    <h4>{% if nur_fr %}En cas de doute{% else %}If in doubt{% endif %}</h4>
    <p>{% if nur_fr %}Si vous suivez un traitement ou avez un problème de peau ou des yeux, demandez l’avis de votre médecin avant d’utiliser NŪR Protocol. C’est un appareil de soin cosmétique&nbsp;: il ne traite aucune maladie.{% else %}If you are under treatment or have a skin or eye condition, ask your doctor before using NŪR Protocol. It is a cosmetic skincare device and does not treat any disease.{% endif %}</p>
    <p>{% if nur_fr %}Pour aller plus loin, lisez notre article <a href="{{ nur_root }}/blogs/news/masque-led-visage-danger">masque LED visage, danger ou pas</a> sur le blog.{% else %}To learn more, read our blog article on whether <a href="{{ nur_root }}/blogs/news/led-face-mask-side-effects">LED face masks are safe</a>.{% endif %}</p>
  </div>
</dialog>

<dialog class="nur-drawer" id="nur-drawer-award" aria-labelledby="nur-drawer-award-title">
  <div class="nur-drawer__head">
    <h3 class="nur-drawer__title" id="nur-drawer-award-title">{% if nur_fr %}Distinction{% else %}Award{% endif %}</h3>
    <button type="button" class="nur-drawer__close" data-nur-close aria-label="{% if nur_fr %}Fermer{% else %}Close{% endif %}"><svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
  </div>
  <div class="nur-drawer__body">
    <img class="nur-award__photo" src="{{ 'myriam-woha-award-crop.webp' | asset_url }}" width="800" height="977" loading="lazy" alt="{% if nur_fr %}Myriam, fondatrice de Nur Protocol, aux Women of Heart Awards à Dubaï{% else %}Myriam, founder of Nur Protocol, at the Women of Heart Awards in Dubai{% endif %}">
    <span class="nur-award__tag">Women of Heart Awards &middot; {% if nur_fr %}Dubaï{% else %}Dubai{% endif %} 2025</span>
    <h4 class="nur-award__title">Business Leader in AI Beauty and Skincare</h4>
    <p>{% if nur_fr %}En 2025, Myriam, fondatrice de NŪR Protocol, a été distinguée aux Women of Heart Awards à Dubaï, dans la catégorie «&nbsp;Business Leader in AI Beauty and Skincare&nbsp;». Le prix lui a été remis par S.E. Dr Desziree Richardson.{% else %}In 2025, Myriam, founder of NŪR Protocol, was honoured at the Women of Heart Awards in Dubai as Business Leader in AI Beauty and Skincare. The award was presented by H.E. Dr. Desziree Richardson.{% endif %}</p>
    <p>{% if nur_fr %}C’est cette expertise de l’IA appliquée à la beauté et au soin de la peau qui est au cœur de NŪR Skincoach.{% else %}That same expertise in AI for beauty and skincare is at the heart of NŪR Skincoach.{% endif %}</p>
    <p><a href="{{ nur_root }}/pages/about">{% if nur_fr %}Découvrir l’histoire de NŪR Protocol{% else %}Read the NŪR Protocol story{% endif %}</a></p>
  </div>
</dialog>

<script>
  (function () {
    document.querySelectorAll('[data-nur-drawer]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var d = document.getElementById(btn.getAttribute('data-nur-drawer'));
        if (d && typeof d.showModal === 'function') { d.showModal(); }
      });
    });
    document.querySelectorAll('.nur-drawer').forEach(function (d) {
      d.addEventListener('click', function (e) {
        if (e.target === d || e.target.closest('[data-nur-close]')) { d.close(); }
      });
    });
  })();
</script>

{%- liquid
  assign nur_fr = false
  if request.locale.iso_code == 'fr'
    assign nur_fr = true
  endif
  assign nur_root = ''
  if nur_fr
    assign nur_root = '/fr'
  endif
  assign nur_product = closest.product | default: product
  assign nur_price = nur_product.selected_or_first_available_variant.price
  assign nur_third = nur_price | divided_by: 3
  assign nur_klarna = false
  if cart.currency.iso_code == 'EUR'
    assign nur_klarna = true
  endif
-%}
{%- comment -%}
  Product-page content section, English and French, each with its own copy and
  its own FAQPage JSON-LD. English: the SEO consultant's brief of 2026-11-21 (UAE
  landing page). French: written for France, same structure, delivery adapted.
  Generated by tools/build_seo_en_section.py: the FAQPage JSON-LD and the visible
  FAQ come from the same strings, so they match character for character.
  FAQ answers sit in <details>: still in the DOM, so readable by Google.
{%- endcomment -%}
{%- unless nur_fr -%}
<style>
  /* Editorial grid: every section = narrow heading column + text column, all left-aligned on one shared width. */
  .nur-seo { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; color: #1A1A1A; max-width: 1120px; margin: 0 auto; padding: 72px 0 0; }
  .nur-seo__row { display: grid; grid-template-columns: 300px minmax(0, 1fr); column-gap: 72px; padding: 56px 0; border-top: 1px solid #E4DFD5; }
  .nur-seo__row:first-child { border-top: 0; padding-top: 0; }
  .nur-seo__label { align-self: start; }
  .nur-seo__idx { display: block; font-size: 11px; font-weight: 600; letter-spacing: 2.5px; text-transform: uppercase; color: #C8A96E; margin-bottom: 14px; }
  .nur-seo h2 { font-size: 26px; font-weight: 500; line-height: 1.25; letter-spacing: -0.3px; margin: 0; color: #1A1A1A; }
  .nur-seo h3 { font-size: 15px; font-weight: 700; line-height: 1.4; margin: 0 0 6px; color: #1A1A1A; }
  .nur-seo p, .nur-seo dd { font-size: 15px; line-height: 1.75; color: #4A4A4A; }
  .nur-seo p { margin: 0 0 14px; text-align: justify; hyphens: auto; -webkit-hyphens: auto; }
  .nur-seo p:last-child { margin-bottom: 0; }
  .nur-seo a { color: #1A1A1A; text-decoration: underline; text-underline-offset: 3px; }
  .nur-seo__lead { font-size: 17px !important; line-height: 1.7 !important; color: #1A1A1A !important; }
  .nur-seo__note { font-size: 13px !important; color: #8A8A8A !important; margin-top: 24px !important; }
  /* Skincoach cards: three equal columns inside the text column */
  .nur-seo__cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; margin-top: 32px; }
  .nur-seo__card-img { display: block; width: 100%; height: auto; aspect-ratio: 1 / 1; object-fit: cover; margin-bottom: 16px; }
  .nur-seo__card h3 { min-height: 42px; }
  .nur-seo__card p { font-size: 14px; line-height: 1.65; text-align: left; hyphens: manual; -webkit-hyphens: manual; }
  .nur-seo__num { display: block; font-size: 12px; font-weight: 600; letter-spacing: 1px; color: #C8A96E; margin-bottom: 8px; }
  /* Wavelengths: aligned two-column list */
  .nur-seo__waves { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 40px; margin-top: 28px; }
  .nur-seo__wave { display: grid; grid-template-columns: 28px minmax(0, 1fr); column-gap: 16px; align-items: start; }
  .nur-seo__dot { width: 28px; height: 28px; border-radius: 50%; margin-top: 1px; }
  .nur-seo__wave h3 { font-size: 14px; margin-bottom: 4px; }
  .nur-seo__wave p { font-size: 14px; line-height: 1.6; text-align: left; }
  /* Session: numbered two-column list */
  .nur-seo__steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 40px; }
  .nur-seo__step { display: grid; grid-template-columns: 28px minmax(0, 1fr); column-gap: 16px; }
  .nur-seo__step .nur-seo__num { margin: 2px 0 0; }
  .nur-seo__step p { font-size: 14px; line-height: 1.6; text-align: left; }
  /* Specs: one clean table */
